create table public.campus_student_plans (user_id uuid primary key default auth.uid(), plan jsonb not null default '{}'::jsonb check(jsonb_typeof(plan)='object' and octet_length(plan::text)<=150000));
grant select,insert,update on public.campus_student_plans to authenticated;
grant all on public.campus_student_plans to service_role;
alter table public.campus_student_plans enable row level security;
create policy student_plan_owner on public.campus_student_plans for all to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));
alter table public.events add column visibility text not null default 'all' check(visibility in ('university','all')), add column host_university text not null default '', add column city text not null default '', add column poster text not null default '', add column registration_url text not null default '' check(registration_url='' or registration_url ~ '^https://[^[:space:]]+$'), add column capacity integer check(capacity>0), add column outcomes text not null default '', add column paid boolean not null default false, add column critical boolean not null default false, add constraint campus_event_poster_owner check(poster='' or split_part(poster,'/',1)=owner::text);
update public.events e set host_university=p.university from public.profiles p where p.id=e.owner;
create function public.campus_event_host() returns trigger language plpgsql set search_path='' as $$ begin if tg_op='UPDATE' then new.host_university:=old.host_university; end if; if new.host_university='' or tg_op='INSERT' then select coalesce((select btrim(p.university) from public.profiles p where p.id=new.owner),'') into new.host_university; end if; if new.visibility='university' and new.host_university='' then raise exception 'Add your university to your profile first.'; end if; return new; end $$;
create trigger campus_event_host before insert or update on public.events for each row execute function public.campus_event_host();
alter policy events_read on public.events using(visibility='all' or owner=(select auth.uid()) or (host_university<>'' and lower(host_university)=(select lower(btrim(p.university)) from public.profiles p where p.id=(select auth.uid()))));
alter policy activity_write on public.event_activity with check(user_id=(select auth.uid()) and exists(select 1 from public.events e where e.id=event_id and (kind='saved' or e.deadline>=now())));
create policy campus_event_poster_view on storage.objects for select to authenticated using(bucket_id='campus-media' and exists(select 1 from public.events e where e.poster=name));
create or replace function public.campus_publish_notice() returns trigger language plpgsql security definer set search_path='' as $$ begin if tg_table_name='events' then insert into public.notifications(user_id,kind,title,body) select p.id,'event','New campus event',new.title from public.profiles p where p.id<>new.owner and (new.visibility='all' or lower(btrim(p.university))=lower(new.host_university)) and coalesce(p.preferences->>'event','true')='true'; elsif new.urgent then insert into public.notifications(user_id,kind,title,body) select p.id,'announcement','Important campus announcement',new.title from public.profiles p where p.id<>new.owner and coalesce(p.preferences->>'announcement','true')='true'; end if; return new; end $$;
create function public.campus_check_capacity() returns trigger language plpgsql security definer set search_path='' as $$ declare available integer; begin if new.kind='registered' then perform pg_advisory_xact_lock(hashtextextended(new.event_id::text,0)); select e.capacity into available from public.events e where e.id=new.event_id; if available is not null and (select count(*) from public.event_activity a where a.kind='registered' and a.event_id=new.event_id)>=available then raise exception 'This event is full.'; end if; end if; return new; end $$;
revoke all on function public.campus_check_capacity() from public;
create trigger campus_capacity before insert on public.event_activity for each row execute function public.campus_check_capacity();
create function public.campus_critical_rsvps() returns table(id uuid,title text,starts_at timestamptz,rsvps bigint) language plpgsql stable security definer set search_path='' as $$ begin if not public.campus_role('admin') then raise exception 'Not authorized'; end if; return query select e.id,e.title,e.starts_at,count(a.user_id) from public.events e join public.profiles p on p.id=auth.uid() and btrim(p.university)<>'' and lower(btrim(p.university))=lower(e.host_university) left join public.event_activity a on a.event_id=e.id and a.kind='registered' where e.critical and e.starts_at>=now() group by e.id having count(a.user_id)<5 order by e.starts_at limit 20; end $$;
revoke all on function public.campus_critical_rsvps() from public; grant execute on function public.campus_critical_rsvps() to authenticated;